function INTERLEAVING-DISTANCE(w_F, w_G, simplices):
    # w_F, w_G : maps from simplex to real birth time
    # simplices : the 2^|V| subsets of the vertex set
    best <- 0.0
    for sigma in simplices:
        gap <- | w_F(sigma) - w_G(sigma) |
        if gap > best:
            best <- gap
    return best        # = eInterleavingDist(F, G), exactly (Theorem 3.5)

function DIAM-FILTRATION(d, vertices):
    # d : symmetric distance matrix on the vertices
    weight <- empty map
    for sigma in subsets(vertices):
        m <- 0.0
        for each unordered pair {x, y} subseteq sigma:
            m <- max(m, d(x, y))
        weight[sigma] <- m       # diameter; 0 if |sigma| < 2
    return weight                 # a monotone weight function (a Filtration)

