function OPTIMAL-INTERLEAVING(w_F, w_G, simplices):
    D <- 0.0
    witness <- none
    for sigma in simplices:
        gap <- | w_F(sigma) - w_G(sigma) |
        if gap > D:
            D <- gap
            witness <- sigma
    # D is an admissible shift (stability_supDist): F and G are D-interleaved.
    # witness realizes the gap D, so no shift < D can interleave (Theorem 3.1).
    return (D, witness)
